    return th if h % th == 0 else h


def _softmax0(x):
    m = jnp.max(x, axis=0, keepdims=True)
    e = jnp.exp(x - m)
    return e * (1.0 / jnp.sum(e, axis=0, keepdims=True))


def _k(s_ref, t_ref, o_ref, acc_ref, *, inv_n):
    first = (pl.program_id(0) == 0) & (pl.program_id(1) == 0)
    last = (pl.program_id(0) == pl.num_programs(0) - 1) & (pl.program_id(1) == pl.num_programs(1) - 1)

    @pl.when(first)
    def _():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    d = _softmax0(s_ref[0].astype(jnp.float32)) - _softmax0(t_ref[0].astype(jnp.float32))
    acc_ref[...] += jnp.sum(d * d, axis=0)

    @pl.when(last)
    def _():
        o_ref[...] = (jnp.sum(acc_ref[...], keepdims=True) * inv_n).astype(o_ref.dtype)


def workload(y_s, y_t):
