    th = _row_tile(h, w, c)
    spec = pl.BlockSpec((1, c, th, w), lambda i, j: (i, 0, j, 0))
    out = pl.pallas_call(
        functools.partial(_k, inv_n=1.0 / (b * c * h * w)),
        out_shape=jax.ShapeDtypeStruct((1, 1), y_s.dtype),
        grid=(b, h // th),
        in_specs=[spec, spec],
        out_specs=pl.BlockSpec((1, 1), lambda i, j: (0, 0)),
        scratch_shapes=[pltpu.VMEM((th, w), jnp.float32)],
        compiler_params=pltpu.CompilerParams(dimension_semantics=("arbitrary", "arbitrary")),
    )(y_s, y_t)
    return out.reshape(())

